actions.script:
// Constructs an isolated, mock execution context to force a qjson compile pass
// through your live DeterministicVueRenderer class.
String screenLocation = "component://${targetComponent}/${artifactPath}"

try {
    // Leverages Moqui's native ScreenFacade to build a render pass programmatically
    def renderComm = ec.screen.makeRender()
        .withScreen(screenLocation)
        .renderMode("qjson") // Tells ScreenRenderImpl to activate our custom renderer!

    StringWriter writer = new StringWriter()
    renderComm.withWriter(writer).render()

    // Slurp the generated JSON tree straight back into an operational Map object
    def jsonMap = new groovy.json.JsonSlurper().parseText(writer.toString())
    context.blueprintJson = jsonMap
} catch (Exception e) {
    ec.logger.error("❌ [AGI-IDE SERVICE ERROR] Failed to serialize artifact tree: " + e.getMessage(), e)
    context.blueprintJson = [name: "Error", attributes: [text: e.getMessage()]]
}
